update public.spell_catalog set
name_ru='Кислотные брызги', casting_time='1 действие', spell_range='60 футов', area='Сфера радиусом 5 футов', duration='Мгновенно', components=array['В','С'], material=null,
check_type='Спасбросок Ловкости', damage='1к6 кислотой при провале',
effect_summary=$$Выбираешь точку в пределах дистанции; в ней лопается кислотный пузырь. Все существа в сфере радиусом 5 футов совершают спасбросок Ловкости и при провале получают 1к6 урона кислотой.$$,
upcast='На 5 уровне урон становится 2к6, на 11 — 3к6, на 17 — 4к6.', notes='При успешном спасброске урона нет.',
author_description=$$Создаёшь пузырь кислоты и отправляешь его туда, где кто-то явно слишком хорошо проводил день. Пузырь лопается на небольшой площади, а все внутри проверяют, достаточно ли быстро умеют отскакивать от химии.$$,
author_comment=$$Маленький шар кислоты. Потому что обычной враждебности приключенцам, видимо, недостаточно.$$, updated_at=now() where slug='acid-splash';

update public.spell_catalog set
name_ru='Леденящее прикосновение', casting_time='1 действие', spell_range='Касание', area='1 существо в пределах досягаемости', duration='Мгновенно', components=array['В','С'], material=null,
check_type='Рукопашная атака заклинанием', damage='1к10 некротического урона',
effect_summary=$$Совершаете рукопашную атаку заклинанием. При попадании цель получает 1к10 некротического урона и не может восстанавливать HP до конца вашего следующего хода.$$,
upcast='На 5 уровне урон становится 2к10, на 11 — 3к10, на 17 — 4к10.', notes='Запрет на восстановление HP действует только при попадании.',
author_description=$$Касаешься цели холодом могилы. Если попал, она не только получает некротический урон, но и на короткое время лишается возможности залечить последствия твоего дружелюбного прикосновения.$$,
author_comment=$$Наконец название не врёт: теперь действительно надо подойти и потрогать. Некроманты добились тактильного контакта.$$, updated_at=now() where slug='chill-touch';

update public.spell_catalog set
name_ru='Пляшущие огоньки', casting_time='1 действие', spell_range='120 футов', area='До 4 огоньков', duration='Концентрация, до 1 минуты', components=array['В','С','М'], material='кусочек фосфора',
check_type='', damage='',
effect_summary=$$Создаёте до четырёх огоньков размером с факел. Каждый даёт тусклый свет в радиусе 10 футов. Вместо четырёх огней их можно объединить в одну светящуюся фигуру Среднего размера, смутно похожую на человека.$$,
upcast='', notes=$$Бонусным действием можно переместить огоньки до 60 футов, оставаясь в пределах дистанции заклинания. Каждый огонёк должен находиться не дальше 20 футов от другого огонька этого заклинания; вышедший за пределы дистанции исчезает.$$,
author_description=$$До четырёх маленьких источников света зависают там, где ты им скажешь. Можно сделать фонари, сферы или собрать всё в одну подозрительно человекоподобную фигуру — отличный способ напугать стражника, который и так не выспался.$$,
author_comment=$$Если четыре светящихся шара не решают проблему, собери из них человека. Люди почему-то пугаются людей сильнее.$$, updated_at=now() where slug='dancing-lights';

update public.spell_catalog set
name_ru='Искусство друидов', casting_time='1 действие', spell_range='30 футов', area='Зависит от эффекта; максимум куб 5 футов', duration='Мгновенно; прогноз погоды держится 1 раунд', components=array['В','С'], material=null,
check_type='', damage='',
effect_summary=$$Создаёте один безвредный природный эффект: предсказываете погоду на следующие 24 часа, заставляете цветок распуститься или почку раскрыться, создаёте небольшой природный сенсорный эффект либо зажигаете или тушите свечу, факел или костёр.$$,
upcast='', notes='Сенсорный эффект должен помещаться в куб 5 футов. Прогноз относится к вашему текущему местоположению.',
author_description=$$Друид просит природу сделать что-нибудь маленькое и показательное: сообщить погоду, распустить цветок, пошуршать листьями или разобраться с костром. В кои-то веки природа отвечает без попытки откусить кому-нибудь руку.$$,
author_comment=$$Мило. Безопасно. Подозрительно. Обычно после цветочков они превращаются в медведя.$$, updated_at=now() where slug='druidcraft';

update public.spell_catalog set
name_ru='Мистический заряд', casting_time='1 действие', spell_range='120 футов', area='1 существо или объект на луч', duration='Мгновенно', components=array['В','С'], material=null,
check_type='Дальняя атака заклинанием для каждого луча', damage='1к10 силового урона за попавший луч',
effect_summary=$$Выпускаете луч потрескивающей энергии. Для каждого луча совершаете отдельную дальнюю атаку заклинанием; при попадании цель получает 1к10 силового урона.$$,
upcast=$$На 5 уровне создаёт 2 луча, на 11 — 3, на 17 — 4. Лучи можно направлять в одну или разные цели; для каждого делается отдельный бросок атаки.$$, notes='',
author_description=$$Фирменный аргумент варлока: направить на проблему луч чужой, плохо объяснимой силы. Работает достаточно хорошо, чтобы большинство из них перестало задавать вопросы о том, что именно было написано мелким шрифтом в договоре.$$,
author_comment=$$Продал душу, получил дальнобойный луч. Банки хотя бы дают ручку.$$, updated_at=now() where slug='eldritch-blast';

update public.spell_catalog set
name_ru='Элементализм', casting_time='1 действие', spell_range='30 футов', area='Обычно куб 5 футов; лепка — объём до куба 1 фут', duration='Мгновенно; отдельные эффекты до 1 минуты или 1 часа', components=array['В','С'], material=null,
check_type='', damage='',
effect_summary=$$Выбираете один небольшой эффект управления стихией: создаёте ветер в кубе 5 футов; покрываете участок 5×5 футов пылью или песком либо пишете слово на земле; создаёте безвредные угли и цветной ароматный дым, способный зажечь свечи, факелы или лампы; создаёте прохладный туман или чашку чистой воды; либо придаёте небольшому объёму земли, песка, огня, дыма, тумана или воды грубую форму.$$,
upcast='', notes=$$Ветер не открывает удерживаемые двери или ставни. Созданная чашка воды испаряется через 1 минуту. Вылепленная форма должна помещаться в куб 1 фут и держится 1 час.$$,
author_description=$$Немного воздуха, земли, огня или воды — ровно столько, чтобы выглядеть впечатляюще перед человеком, который никогда не видел настоящего мага. Удобно для дыма, мелких трюков, воды и надписей на песке. Для убийства всё ещё придётся постараться обычным способом.$$,
author_comment=$$Повелеваешь стихиями. В пределах примерно одного приличного ведра. Начало карьеры всегда унизительно.$$, updated_at=now() where slug='elementalism';

update public.spell_catalog set
name_ru='Огненный снаряд', casting_time='1 действие', spell_range='120 футов', area='1 существо или объект', duration='Мгновенно', components=array['В','С'], material=null,
check_type='Дальняя атака заклинанием', damage='1к10 огненного урона',
effect_summary=$$Метаете частицу огня в существо или объект. При попадании цель получает 1к10 огненного урона. Воспламеняемый объект загорается, если его никто не носит и не держит.$$,
upcast='На 5 уровне урон становится 2к10, на 11 — 3к10, на 17 — 4к10.', notes='',
author_description=$$Прямолинейный огненный выстрел на хорошую дистанцию. Попал — горит цель. Попал в подходящий бесхозный предмет — горит ещё и он. Волшебники называют это базовой боевой магией; пожарные называют это причиной увольнения.$$,
author_comment=$$Удобное заклинание для тех, кому «Огненный шар» пока не доверили. И правильно сделали.$$, updated_at=now() where slug='fire-bolt';

update public.spell_catalog set
name_ru='Наставление', casting_time='1 действие', spell_range='Касание', area='1 согласное существо', duration='Концентрация, до 1 минуты', components=array['В','С'], material=null,
check_type='', damage='',
effect_summary=$$Касаетесь согласного существа и выбираете один навык. Пока заклинание действует, цель добавляет 1к4 к каждой проверке характеристики, использующей выбранный навык.$$,
upcast='', notes='Навык выбирается при наложении. Требуется концентрация.',
author_description=$$Касаешься товарища и ненадолго делаешь его чуточку компетентнее в одном выбранном навыке. Жрецы обычно называют это божественным наставлением. Я называю это магической подсказкой перед контрольной.$$,
author_comment=$$Если бог действительно всё знает, странно, что от него приходит всего 1к4.$$, updated_at=now() where slug='guidance';

update public.spell_catalog set
name_ru='Свет', casting_time='1 действие', spell_range='Касание', area='1 предмет Большого размера или меньше', duration='1 час', components=array['В','М'], material='светлячок или фосфоресцирующий мох',
check_type='', damage='',
effect_summary=$$Касаетесь предмета Большого размера или меньше, который не носит и не держит другое существо. Он излучает яркий свет в радиусе 20 футов и тусклый ещё на 20 футов. Цвет выбираете сами.$$,
upcast='', notes='Непрозрачное покрытие полностью блокирует свет. Если наложить «Свет» ещё раз, предыдущий эффект заканчивается.',
author_description=$$Заставляешь предмет светиться целый час. Не требует концентрации, не пытается тебя убить и даже позволяет выбрать цвет. Редкий пример магии, с которой справляется обычный фонарь, но без масла и запаха.$$,
author_comment=$$Если партия всё равно идёт в темноту без источника света, магия здесь уже не поможет.$$, updated_at=now() where slug='light';